problems.solutionCode:
function traceAttemptCount() {
  const events = [];
  const frames = [{ remaining: 2, returning: false }];
  while (frames.length > 0) {
    const frame = frames.pop();
    if (frame.returning) {
      events.push('leave:' + frame.remaining);
      continue;
    }
    events.push('enter:' + frame.remaining);
    if (frame.remaining === 0) {
      events.push('base');
      continue;
    }
    frames.push({ remaining: frame.remaining, returning: true });
    frames.push({ remaining: frame.remaining - 1, returning: false });
  }
  return [events.join('|')];
}

module.exports = { traceAttemptCount };

