  for (const child of node.children) visit(child, events);
  events.push('leave:' + node.id);
}
const org = { id: 'root', children: [
  { id: 'east', children: [] },
  { id: 'west', children: [{ id: 'desk', children: [] }] }
] };
const events = [];
visit(org, events);
console.log(events.join('|'));
```

**Requirements:**
