problems.solutionCode:
function traceOrganizationExport() {
  const events = [];
  const stack = [{ node: { id: 'root', children: [{ id: 'east', children: [] }, { id: 'west', children: [{ id: 'desk', children: [] }] }] }, leaving: false }];
  while (stack.length > 0) {
    const frame = stack.pop();
    if (frame.leaving) {
      events.push('leave:' + frame.node.id);
      continue;
    }
    events.push('enter:' + frame.node.id);
    stack.push({ node: frame.node, leaving: true });
    for (let index = frame.node.children.length - 1; index >= 0; index -= 1) {
      stack.push({ node: frame.node.children[index], leaving: false });
    }
  }
  return [events.join('|')];
}

module.exports = { traceOrganizationExport };

