problems.solutionCode:
function traceRetrySchedule() {
  const attempts = [];
  let remaining = 3;
  while (remaining > 1) {
    attempts.push('try-' + remaining);
    remaining -= 1;
  }
  attempts.push('stop');
  return [attempts.join('>')];
}

module.exports = { traceRetrySchedule };

