problems.solutionCode:
function traceRegionalDepth() {
  const routes = [];
  for (const region of ['north', 'south']) {
    let currentRegion = region;
    let depth = 0;
    while (depth <= 1) {
      routes.push(currentRegion + ':' + depth);
      currentRegion += '-child';
      depth += 1;
    }
  }
  return [routes.join('|')];
}

module.exports = { traceRegionalDepth };

