function traceFolderQuota() {
  const tree = { own: 2, children: [
    { own: 1, children: [] },
    { own: 3, children: [{ own: 4, children: [] }] }
  ] };
  function quota(folder) {
    if (folder === null) return 0;
    let total = folder.own;
    for (const child of folder.children) total += quota(child);
    return total;
  }
  return [String(quota(tree))];
}

module.exports = { traceFolderQuota };

